import React, { useState } from 'react';
import { StyleSheet, Text, View, TextInput, Button, TouchableOpacity, ImageBackground } from 'react-native';

const App: React.FC = () => {
  const [username, setUsername] = useState<string>('');
  const [password, setPassword] = useState<string>('');

  return (
    <ImageBackground source={{ uri: 'your-background-image-url' }} style={styles.background}>
      <View style={styles.container}>
        <Text style={styles.heading}>Allowance Calculator</Text>

        <TextInput
          style={styles.input}
          placeholder="Username"
          onChangeText={setUsername}
          value={username}
        />

        <TextInput
          style={styles.input}
          placeholder="Password"
          secureTextEntry={true}
          onChangeText={setPassword}
          value={password}
        />

        <View style={styles.buttonContainer}>
          <Button
            title="Login"
            color="#FFFFFF"
            onPress={() => console.log('Login Pressed')}
          />
        </View>

        <TouchableOpacity
          style={styles.buttonGoogle}
          onPress={() => console.log('Continue with Google Pressed')}
        >
          <Text style={styles.buttonGoogleText}>Continue with Google</Text>
        </TouchableOpacity>
      </View>
    </ImageBackground>
  );
}

const styles = StyleSheet.create({
  background: {
    flex: 1,
    resizeMode: 'cover',
  },
  container: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    padding: 20,
    backgroundColor: 'rgba(255, 255, 255, 0.8)',
    marginHorizontal: 40,
    borderRadius: 10,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.25,
    shadowRadius: 3.84,
    elevation: 5,
  },
  heading: {
    fontSize: 28,
    fontWeight: 'bold',
    color: '#333',
    marginBottom: 30,
  },
  input: {
    width: '100%',
    height: 50,
    backgroundColor: '#fff',
    padding: 10,
    marginBottom: 15,
    borderRadius: 5,
    borderWidth: 1,
    borderColor: '#ccc',
  },
  buttonContainer: {
    width: '100%',
    backgroundColor: '#4CAF50',
    borderRadius: 5,
  },
  buttonGoogle: {
    width: '100%',
    backgroundColor: '#4285F4',
    padding: 15,
    borderRadius: 5,
    marginTop: 10,
    alignItems: 'center',
  },
  buttonGoogleText: {
    color: 'white',
    fontWeight: 'bold',
  },
});

export default App;
